{"metadata":{"kernelspec":{"language":"python","display_name":"Python 3","name":"python3"},"language_info":{"name":"python","version":"3.13.15","mimetype":"text/x-python","codemirror_mode":{"name":"ipython","version":3},"pygments_lexer":"ipython3","nbconvert_exporter":"python","file_extension":".py"},"kaggle":{"accelerator":"none","dataSources":[],"isInternetEnabled":true,"language":"python","sourceType":"notebook","isGpuEnabled":false}},"nbformat_minor":4,"nbformat":4,"cells":[{"cell_type":"code","source":"\"\"\"\nA simple utility script containing helper functions for data manipulation and evaluation.\n\"\"\"\n\nimport numpy as np\nimport pandas as pd\n\n\ndef summarize_dataframe(df: pd.DataFrame) -> dict:\n  \"\"\"Returns basic shape and missing value counts for a pandas DataFrame.\"\"\"\n  summary = {\n      \"rows\": df.shape[0],\n      \"columns\": df.shape[1],\n      \"missing_values\": df.isnull().sum().to_dict(),\n  }\n  return summary\n\n\ndef calculate_rmse(y_true: np.ndarray, y_pred: np.ndarray) -> float:\n  \"\"\"Calculates Root Mean Squared Error between true and predicted arrays.\"\"\"\n  return float(np.sqrt(np.mean((y_true - y_pred) ** 2)))","metadata":{"_uuid":"8f2839f25d086af736a60e9eeb907d3b93b6e0e5","_cell_guid":"b1076dfc-b9ad-4769-8c92-a6c4dae69d19","trusted":true,"execution":{"iopub.status.busy":"2026-10-31T13:01:11.708279Z","iopub.execute_input":"2026-10-31T13:01:11.708538Z","iopub.status.idle":"2026-10-31T13:01:13.14159Z","shell.execute_reply.started":"2026-10-31T13:01:11.708505Z","shell.execute_reply":"2026-10-31T13:01:13.140695Z"}},"outputs":[],"execution_count":1}]}